// Detects if monthly (day=1) or weekly from which trigger fired
const now = new Date();
const day = now.getDate();
const isMonthly = day === 1;

let startDate, endDate;
if (isMonthly) {
  const y = now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear();
  const m = now.getMonth() === 0 ? 11 : now.getMonth() - 1;
  startDate = new Date(y, m, 1);
  endDate = new Date(y, m + 1, 0);
} else {
  endDate = new Date(now);
  startDate = new Date(now);
  startDate.setDate(now.getDate() - 7);
}

const fmt = d => d.toISOString().split('T')[0];

return [{ json: {
  period: isMonthly ? 'Mensal' : 'Semanal',
  start_date: fmt(startDate),
  end_date: fmt(endDate)
}}];

// ⚠️ EDIT: map your origin_id → marketing investment for the period
// Get origin IDs from PipeRun Settings > Origins
const investments = [
  { origin_id: 1, investment: 5000 },
  { origin_id: 2, investment: 3000 },
  { origin_id: 3, investment: 800 },
  { origin_id: 4, investment: 0 }
];
return investments.map(i => ({ json: i }));

const periodData   = $('Set Period').first().json;
const originsRaw   = $('Listar origens de oportunidades').all();
const dealsRaw     = $('Listar oportunidades').all();
const investItems  = $('Investment Data').all();
const pipelinesRaw = $('Listar funis').all();

const origins = originsRaw.flatMap(i => Array.isArray(i.json?.data) ? i.json.data : []);
const originMap = Object.fromEntries(origins.map(o => [String(o.id), o.name]));

const pipelines = pipelinesRaw.flatMap(i => Array.isArray(i.json?.data) ? i.json.data : []);
const pipelineMap = Object.fromEntries(pipelines.map(p => [String(p.id), p.name]));

const deals = dealsRaw.flatMap(i => Array.isArray(i.json?.data) ? i.json.data : []);
const investMap = Object.fromEntries(investItems.map(i => [String(i.json.origin_id), Number(i.json.investment)]));

const agg = {};
for (const deal of deals) {
  const pid = String(deal.pipeline_id ?? 'sem_pipeline');
  const oid = String(deal.origin_id ?? 'sem_origem');
  if (!agg[pid]) agg[pid] = {};
  if (!agg[pid][oid]) agg[pid][oid] = { leads: 0, won: 0, lost: 0, open: 0 };
  agg[pid][oid].leads++;
  if      (deal.status === 1) agg[pid][oid].won++;
  else if (deal.status === 3) agg[pid][oid].lost++;
  else                        agg[pid][oid].open++;
}

const pipelineRows = Object.entries(agg).map(([pid, originsData]) => {
  const originRows = Object.entries(originsData).map(([oid, c]) => {
    const investment = investMap[oid] ?? 0;
    return {
      origin_id:   isNaN(Number(oid)) ? oid : Number(oid),
      origin_name: originMap[oid] ?? oid,
      leads: c.leads, won: c.won, lost: c.lost, open: c.open,
      investment,
      cpl: c.leads > 0 ? +(investment / c.leads).toFixed(2) : null,
      cac: c.won   > 0 ? +(investment / c.won).toFixed(2)   : null,
    };
  }).sort((a, b) => b.leads - a.leads);

  const tLeads  = originRows.reduce((s, r) => s + r.leads, 0);
  const tWon    = originRows.reduce((s, r) => s + r.won,   0);
  const tInvest = originRows.reduce((s, r) => s + r.investment, 0);
  return {
    pipeline_id:      isNaN(Number(pid)) ? pid : Number(pid),
    pipeline_name:    pipelineMap[pid] ?? pid,
    total_leads:      tLeads,
    total_won:        tWon,
    total_investment: tInvest,
    overall_cpl:      tLeads > 0 ? +(tInvest / tLeads).toFixed(2) : null,
    overall_cac:      tWon   > 0 ? +(tInvest / tWon).toFixed(2)   : null,
    origins:          originRows,
  };
}).sort((a, b) => b.total_leads - a.total_leads);

const totalLeads  = pipelineRows.reduce((s, r) => s + r.total_leads, 0);
const totalWon    = pipelineRows.reduce((s, r) => s + r.total_won,   0);
const totalInvest = pipelineRows.reduce((s, r) => s + r.total_investment, 0);

return [{ json: {
  period:           periodData.period,
  start_date:       periodData.start_date,
  end_date:         periodData.end_date,
  total_leads:      totalLeads,
  total_won:        totalWon,
  total_investment: totalInvest,
  overall_cpl:      totalLeads > 0 ? +(totalInvest / totalLeads).toFixed(2) : null,
  overall_cac:      totalWon   > 0 ? +(totalInvest / totalWon).toFixed(2)   : null,
  pipelines:        pipelineRows,
}}];

const d = $input.first().json;

const R = n =>
  n != null
    ? 'R$ ' + Number(n).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
    : '—';

const fields = [];

for (const pipeline of d.pipelines) {
  if (fields.length >= 24) {
    fields.push({
      name:   '+' + (d.pipelines.length - fields.length) + ' outros funis',
      value:  'Veja o relatório completo no PipeRun',
      inline: false,
    });
    break;
  }

  const originLines = pipeline.origins.slice(0, 8).map(r =>
    '• ' + r.origin_name + ': **' + r.leads + '** leads | **' + r.won + '** vendas | CPL: ' + R(r.cpl) + ' | CAC: ' + R(r.cac)
  );
  if (pipeline.origins.length > 8) {
    originLines.push('• +' + (pipeline.origins.length - 8) + ' outras origens');
  }

  fields.push({
    name: ('🔹 ' + pipeline.pipeline_name + ' — ' + pipeline.total_leads + ' leads | ' + pipeline.total_won + ' vendas').slice(0, 256),
    value: [
      'Invest.: ' + R(pipeline.total_investment) + ' | CPL: ' + R(pipeline.overall_cpl) + ' | CAC: ' + R(pipeline.overall_cac),
      ...originLines,
    ].join('\n').slice(0, 1024),
    inline: false,
  });
}

const color = d.period === 'Mensal' ? 0x5865F2 : 0x57F287;

const payload = {
  embeds: [{
    title: '📊 Relatório ' + d.period + ' — PipeRun',
    description: [
      '📅 Período: **' + d.start_date + '** até **' + d.end_date + '**',
      '',
      '🎯 Leads Totais: **' + d.total_leads + '** | ✅ Vendas: **' + d.total_won + '**',
      '💰 Investimento Total: **' + R(d.total_investment) + '**',
      '📉 CPL Médio: **' + R(d.overall_cpl) + '** | 🏆 CAC Médio: **' + R(d.overall_cac) + '**',
    ].join('\n'),
    color,
    fields,
    footer: {
      text: 'Gerado automaticamente em ' + new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    },
  }],
};

return [{ json: { payload } }];

const now = new Date();
const day = now.getDate();
const isMonthly = day === 1;

let startDate, endDate;
if (isMonthly) {
  const y = now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear();
  const m = now.getMonth() === 0 ? 11 : now.getMonth() - 1;
  startDate = new Date(y, m, 1);
  endDate   = new Date(y, m + 1, 0);
} else {
  endDate   = new Date(now);
  startDate = new Date(now);
  startDate.setDate(now.getDate() - 7);
}

const fmt = d => d.toISOString().split('T')[0];

return [{ json: {
  period:     isMonthly ? 'Mensal' : 'Semanal',
  start_date: fmt(startDate),
  end_date:   fmt(endDate)
}}];

const raw = $input.first().json;
if (raw.error) throw new Error(`Facebook API error: ${raw.error.message}`);
const campaigns = raw.data || [];

const leadTypes = [
  'lead',
  'onsite_conversion.lead_grouped',
  'offsite_conversion.fb_pixel_lead',
  'contact',
];

return campaigns
  .map(c => {
    const actions = c.actions || [];
    const leads = leadTypes.reduce((sum, t) => {
      const a = actions.find(x => x.action_type === t);
      return sum + (a ? parseFloat(a.value) : 0);
    }, 0);
    const spend = parseFloat(c.spend || 0);
    return { json: {
      source: 'Facebook Ads',
      campaign: c.campaign_name || 'Unknown',
      spend,
      leads: Math.round(leads),
      cpl: leads > 0 ? parseFloat((spend / leads).toFixed(2)) : null,
    }};
  })
  .filter(i => i.json.spend > 0);

// Official Google Ads node v1 returns one item per campaign (flat fields).
// Conversions are not exposed — leads set to 0; CPL will show as null.
// If you need conversion data, replace this node with an HTTP Request using GAQL.
return $input.all()
  .map(item => {
    const r = item.json;
    const spend = parseInt(r.costMicros || '0') / 1_000_000;
    return { json: {
      source: 'Google Ads',
      campaign: r.name || 'Unknown',
      spend: parseFloat(spend.toFixed(2)),
      leads: 0,
      cpl: null,
    }};
  })
  .filter(i => i.json.spend > 0);

// Auto-maps ad campaigns → PipeRun origins using:
// 1. Campaign name ↔ origin name substring match (case-insensitive)
// 2. Source-level fallback (Facebook/Meta → facebook origin, Google → google origin)
// 3. Final fallback: 'facebook_unmapped' / 'google_ads_unmapped'
//
// Optional manual overrides (higher priority than auto-match):
const overrides = [
  // { campaign_contains: 'Brand',       origin_id: 1 },
  // { campaign_contains: 'Remarketing', origin_id: 2 },
];

const allItems = $input.all();

// Extract PipeRun origins from merged inputs (items with json.data array)
const origins = allItems
  .flatMap(i => Array.isArray(i.json?.data) ? i.json.data : [])
  .filter(o => o.id && o.name)
  .map(o => ({ id: o.id, name: o.name, lower: o.name.toLowerCase() }));

function findOrigin(source, campaign) {
  const cLower = (campaign ?? '').toLowerCase();
  const sLower = source.toLowerCase();

  // 0. Manual override wins
  const override = overrides.find(m =>
    cLower.includes((m.campaign_contains ?? '').toLowerCase())
  );
  if (override) return override.origin_id;

  // 1. Campaign name contains origin name (e.g. 'Leads Instagram' → origin 'Instagram')
  const byOriginInCampaign = origins.find(o => o.lower.length > 2 && cLower.includes(o.lower));
  if (byOriginInCampaign) return byOriginInCampaign.id;

  // 2. Origin name contains campaign name
  const byCampaignInOrigin = origins.find(o => cLower.length > 3 && o.lower.includes(cLower));
  if (byCampaignInOrigin) return byCampaignInOrigin.id;

  // 3. Source-level fallback
  if (sLower.includes('facebook') || sLower.includes('meta')) {
    const fb = origins.find(o => o.lower.includes('facebook') || o.lower.includes('meta'));
    if (fb) return fb.id;
  }
  if (sLower.includes('google')) {
    const g = origins.find(o => o.lower.includes('google'));
    if (g) return g.id;
  }

  return source === 'Google Ads' ? 'google_ads_unmapped' : 'facebook_unmapped';
}

const adItems = allItems.filter(i =>
  i.json.source === 'Facebook Ads' || i.json.source === 'Google Ads'
);
const mapped = {};

for (const item of adItems) {
  const { source, campaign, spend, leads } = item.json;
  const originId = findOrigin(source, campaign);
  const key = String(originId);

  if (!mapped[key]) mapped[key] = { origin_id: originId, investment: 0, leads_ads: 0, sources: [], matched_campaigns: [] };
  mapped[key].investment += (spend || 0);
  mapped[key].leads_ads  += (leads || 0);
  mapped[key].sources.push(`${source}${campaign ? ': ' + campaign : ''}`);
  if (campaign) mapped[key].matched_campaigns.push(campaign);
}

return Object.values(mapped).map(r => ({ json: r }));

const periodData   = $('Set Period3').first().json;
const originsRaw   = $('Fetch PipeRun Origins1').all();
const dealsRaw     = $('Fetch PipeRun Deals1').all();
const spendItems   = $('Spend-Origin Mapping1').all();
const gaItems      = $('Fetch GA Data1').all();
const pipelinesRaw = $('Fetch PipeRun Pipelines').all();

const origins   = originsRaw.flatMap(i => Array.isArray(i.json?.data) ? i.json.data : []);
const originMap = Object.fromEntries(origins.map(o => [String(o.id), o.name]));

const pipelines   = pipelinesRaw.flatMap(i => Array.isArray(i.json?.data) ? i.json.data : []);
const pipelineMap = Object.fromEntries(pipelines.map(p => [String(p.id), p.name]));

const spendMap = Object.fromEntries(spendItems.map(i => [String(i.json.origin_id), i.json]));

const deals = dealsRaw.flatMap(i => Array.isArray(i.json?.data) ? i.json.data : []);

const agg = {};
for (const deal of deals) {
  const pid = String(deal.pipeline_id ?? 'sem_pipeline');
  const oid = String(deal.origin_id ?? 'sem_origem');
  if (!agg[pid]) agg[pid] = {};
  if (!agg[pid][oid]) agg[pid][oid] = { leads: 0, won: 0, lost: 0, open: 0 };
  agg[pid][oid].leads++;
  if      (deal.status === 1) agg[pid][oid].won++;
  else if (deal.status === 3) agg[pid][oid].lost++;
  else                        agg[pid][oid].open++;
}

const pipelineRows = Object.entries(agg).map(([pid, originsData]) => {
  const originRows = Object.entries(originsData).map(([oid, c]) => {
    const s          = spendMap[oid] ?? {};
    const investment = s.investment ?? 0;
    const leadsAds   = s.leads_ads  ?? 0;
    const cplBase    = leadsAds > 0 ? leadsAds : c.leads;
    return {
      origin_id:   isNaN(Number(oid)) ? oid : Number(oid),
      origin_name: originMap[oid] ?? oid,
      leads_crm:   c.leads,
      leads_ads:   leadsAds,
      won:         c.won,
      investment,
      cpl:         cplBase > 0 ? +(investment / cplBase).toFixed(2) : null,
      cac:         c.won   > 0 ? +(investment / c.won).toFixed(2)   : null,
      sources:     s.sources ?? [],
    };
  }).sort((a, b) => b.leads_crm - a.leads_crm);

  const tLeads  = originRows.reduce((s, r) => s + r.leads_crm, 0);
  const tWon    = originRows.reduce((s, r) => s + r.won,       0);
  const tInvest = originRows.reduce((s, r) => s + r.investment, 0);
  return {
    pipeline_id:      isNaN(Number(pid)) ? pid : Number(pid),
    pipeline_name:    pipelineMap[pid] ?? pid,
    total_leads:      tLeads,
    total_won:        tWon,
    total_investment: tInvest,
    overall_cpl:      tLeads > 0 ? +(tInvest / tLeads).toFixed(2) : null,
    overall_cac:      tWon   > 0 ? +(tInvest / tWon).toFixed(2)   : null,
    origins:          originRows,
  };
}).sort((a, b) => b.total_leads - a.total_leads);

let gaSummary = null;
if (gaItems.length > 0) {
  const raw = gaItems[0].json;
  let m;
  if (Array.isArray(raw.rows)) {
    const row = raw.rows[0] ?? { metricValues: [] };
    m = {};
    (raw.metricHeaders ?? []).forEach((h, j) => { m[h.name] = row.metricValues[j]?.value ?? '0'; });
  } else {
    m = raw;
  }
  gaSummary = {
    totalUsers:      parseInt(m.totalUsers      || 0),
    sessions:        parseInt(m.sessions         || 0),
    screenPageViews: parseInt(m.screenPageViews  || 0),
    engagementRate:  parseFloat(m.engagementRate || 0) * 100,
    eventCount:      parseInt(m.eventCount       || 0),
  };
}

const totalLeads  = pipelineRows.reduce((s, r) => s + r.total_leads,      0);
const totalWon    = pipelineRows.reduce((s, r) => s + r.total_won,         0);
const totalInvest = pipelineRows.reduce((s, r) => s + r.total_investment,  0);

return [{ json: {
  period:           periodData.period,
  start_date:       periodData.start_date,
  end_date:         periodData.end_date,
  total_leads_crm:  totalLeads,
  total_won:        totalWon,
  total_investment: totalInvest,
  overall_cpl:      totalLeads > 0 ? +(totalInvest / totalLeads).toFixed(2) : null,
  overall_cac:      totalWon   > 0 ? +(totalInvest / totalWon).toFixed(2)   : null,
  pipelines:        pipelineRows,
  ga:               gaSummary,
}}];

const d = $input.first().json;
const R = n => n != null
  ? 'R$ ' + Number(n).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
  : '—';
const N = n => n != null ? Number(n).toLocaleString('pt-BR') : '—';

const fields = [];

if (d.ga) {
  fields.push({
    name:  '🌐 Google Analytics',
    value: [
      'Usuários: **' + N(d.ga.totalUsers) + '** | Sessões: **' + N(d.ga.sessions) + '**',
      'Pageviews: **' + N(d.ga.screenPageViews) + '** | Eventos: **' + N(d.ga.eventCount) + '**',
      'Taxa Engajamento: **' + d.ga.engagementRate.toFixed(1) + '%**',
    ].join('\n'),
    inline: false,
  });
}

for (const pipeline of d.pipelines) {
  if (fields.length >= 24) {
    fields.push({
      name:   '+' + (d.pipelines.length - (fields.length - (d.ga ? 1 : 0))) + ' outros funis',
      value:  'Ver relatório completo no PipeRun',
      inline: false,
    });
    break;
  }

  const originLines = pipeline.origins.slice(0, 6).map(r => {
    const inv = r.leads_ads > 0
      ? 'Mídia: **' + N(r.leads_ads) + '**L | Invest.: **' + R(r.investment) + '**'
      : 'Invest.: **' + R(r.investment) + '**';
    return '• ' + r.origin_name + ': CRM **' + r.leads_crm + '**L | **' + r.won + '**V | ' + inv + ' | CPL: **' + R(r.cpl) + '** | CAC: **' + R(r.cac) + '**';
  });
  if (pipeline.origins.length > 6) {
    originLines.push('• +' + (pipeline.origins.length - 6) + ' outras origens');
  }

  fields.push({
    name: ('🔹 ' + pipeline.pipeline_name + ' — ' + pipeline.total_leads + ' leads | ' + pipeline.total_won + ' vendas').slice(0, 256),
    value: [
      'Invest.: ' + R(pipeline.total_investment) + ' | CPL: ' + R(pipeline.overall_cpl) + ' | CAC: ' + R(pipeline.overall_cac),
      ...originLines,
    ].join('\n').slice(0, 1024),
    inline: false,
  });
}

const color = d.period === 'Mensal' ? 0x5865F2 : 0xEB4034;

const payload = {
  embeds: [{
    title: '🏆 Relatório Integrado ' + d.period + ' — Marketing',
    description: [
      '📅 **' + d.start_date + '** até **' + d.end_date + '**',
      '',
      '💰 Investimento Total: **' + R(d.total_investment) + '**',
      '🎯 Leads CRM: **' + d.total_leads_crm + '** | ✅ Vendas: **' + d.total_won + '**',
      '📉 CPL Médio: **' + R(d.overall_cpl) + '** | 🏆 CAC Médio: **' + R(d.overall_cac) + '**',
    ].join('\n'),
    color,
    fields: fields.slice(0, 25),
    footer: {
      text: 'Gerado em ' + new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    },
  }],
};

return [{ json: { payload } }];

